"""Maximum Path Sum in a Grid — rolling DP row with three predecessors.

Time: O(m*n)   Space: O(n)
"""
from typing import List


class Solution:
    def maxPathSum(self, grid: List[List[int]]) -> int:
        n = len(grid[0])
        row = grid[0][:]
        for line in grid[1:]:
            nxt = []
            for j in range(n):
                best = max(row[max(0, j - 1):min(n, j + 2)])
                nxt.append(line[j] + best)
            row = nxt
        return max(row)
